package com.example.urlshortener;
import com.example.urlshortener.dto.*; import com.example.urlshortener.repository.UrlMappingRepository; import com.example.urlshortener.service.UrlShortenerService; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class UrlShortenerServiceTest { @Test void createsShortUrl(){UrlMappingRepository r=Mockito.mock(UrlMappingRepository.class);Mockito.when(r.findByShortCode(Mockito.anyString())).thenReturn(Optional.empty());Mockito.when(r.save(Mockito.any())).thenAnswer(i->i.getArgument(0));var s=new UrlShortenerService(r,"http://localhost:8080");var x=s.create(new CreateUrlRequest("https://example.com",60L));assertEquals(7,x.shortCode().length());assertTrue(x.shortUrl().endsWith(x.shortCode()));assertNotNull(x.expiresAt());} }